void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    vec4 currentFrame = texture(iChannel0, uv); // Webcam input, also go fix channels in buffers
    vec4 delayedFrame = texture(iChannel1, uv); // Delayed frame from Buffer C, assuming Buffer C is linked to iChannel3

    // Calculate the difference between the current and delayed frames
    vec4 diff = abs(currentFrame - delayedFrame);

    // Threshold the difference to filter out minor changes
    float threshold = .2;
    vec4 motion = vec4((diff.r + diff.g + diff.b) > threshold ? 1.0 : 0.0);

    // Invert colors of the current frame
    vec4 invertedColors = vec4(1.0 - currentFrame.rgb, 1.0);

    // Apply the motion mask to the inverted colors
    fragColor = invertedColors * motion;
}

// Buffer A (Captures the current frame and averages with previous frame)
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;
    vec4 currentFrame = texture(iChannel0, uv);
    vec4 previousFrame = texture(iChannel1, uv); // Assuming this buffer's output is fed back into itself

    // Blend the current frame with the previous frame to reduce noise
    float blendFactor = 0.1;  // Adjust this factor to control smoothing
    fragColor = mix(previousFrame, currentFrame, blendFactor);
}

